import re

def split(s, platform='this'):
    """Multi-platform variant of shlex.split() for command-line splitting.
    For use with subprocess, for argv injection etc. Using fast REGEX.

    platform: 'this' = auto from current platform;
              1 = POSIX;
              0 = Windows/CMD
              (other values reserved)
    """
    if platform == 'this':
        platform = os.name
    if platform == 'posix':
        return re.split(r'\s+', s)
    elif platform == 'nt':
        return re.split(r'[\s;]+', s)
    else:
        raise ValueError("Unsupported platform: {}".format(platform))

def parse_frequency(frequency):
    if frequency is None or frequency == "always":
        return None

    parts = frequency.split()
    if len(parts) != 2:
        raise ValueError("Invalid frequency format")

    number = int(parts[0])
    unit = parts[1]

    if unit == "weeks":
        return datetime.timedelta(weeks=number)
    elif unit == "days":
        return datetime.timedelta(days=number)
    elif unit == "hours":
        return datetime.timedelta(hours=number)
    elif unit == "minutes":
        return datetime.timedelta(minutes=number)
    elif unit == "seconds":
        return datetime.timedelta(seconds=number)
    else:
        raise ValueError("Unsupported unit of time")

def _resolve_string(matcher):
    '''
    Get the value from environment given a matcher containing a name and an optional default value.
    If the variable is not defined in environment and no default value is provided, an Error is raised.
    '''
    name = matcher['name']
    default = matcher.get('default', None)
    if name not in os.environ:
        if default is None:
            raise ValueError(f"Environment variable {name} is not defined.")
        else:
            return default
    return os.environ[name]

