    """Call the given command(s)."""

    process = subprocess.Popen(commands, args=args, cwd=cwd, stdout=subprocess.PIPE, stderr=subprocess.PIPE, env=env)

    if verbose:
        print("Running command:", " ".join(commands + args))

    stdout, stderr = process.communicate()

    if verbose:
        print("Command output:", stdout.decode('utf-8'))
        if hide_stderr:
            print("Command error:", stderr.decode('utf-8'))
        else:
            print("Command error:", stderr.decode('utf-8'))

    return stdout, stderr

